fun gao1(a: String, b: String): Int {
    var c = 0
    repeat(4) { i ->
        if (a[i] == b[i]) c += 1
    }
    return c
}

fun gao2(a: String, b: String): Int {
    var c = 0
    repeat(4) { i ->
        if (b.indexOf(a[i]) != -1) c += 1
    }
    return c
}

fun main() {
    val n = readLine()!!.toInt()
    val x = (100..9999).map { String.format("%04d", it) }.toMutableList()
    x.removeIf { it.toByteArray().sorted().distinct().size < 4 }

    repeat(n) {
        val parts = readLine()!!.split(" ")
        var a = parts[0].toInt()
        var b = parts[1].toInt()
        var c = parts[2].toInt()
        val aStr = String.format("%04d", a)
        c += b
        x.removeIf { gao1(it, aStr) != b || gao2(it, aStr) != c }
    }

    when {
        x.isEmpty() -> println("Incorrect data")
        x.size > 1 -> println("Need more data")
        else -> println(x[0])
    }
}

